    masterdns_android_title: "\u0627\u0646\u062F\u0631\u0648\u06CC\u062F (Termux)",
    masterdns_android_steps: "\u06F1. Termux \u0631\u0627 \u0627\u0632 F-Droid \u0646\u0635\u0628 \u06A9\u0646\u06CC\u062F (\u0646\u0647 Play Store)\n\u06F2. \u0628\u0627\u06CC\u0646\u0631\u06CC \u06A9\u0644\u0627\u06CC\u0646\u062A \u0631\u0627 \u062F\u0627\u0646\u0644\u0648\u062F \u0648 \u0627\u0633\u062A\u062E\u0631\u0627\u062C \u06A9\u0646\u06CC\u062F\n\u06F3. \u0641\u0627\u06CC\u0644 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0631\u0627 \u062F\u0631 Termux \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0646\u06CC\u062F\n\u06F4. \u06A9\u0644\u0627\u06CC\u0646\u062A \u0631\u0627 \u0627\u062C\u0631\u0627 \u06A9\u0646\u06CC\u062F\n\u06F5. \u067E\u0631\u0627\u06A9\u0633\u06CC Wi-Fi \u06AF\u0648\u0634\u06CC \u0631\u0627 \u0631\u0648\u06CC 127.0.0.1:18000 \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F",
    masterdns_windows_title: "Windows",
    masterdns_windows_steps: "\u06F1. \u0631\u0648\u06CC Download Config \u062F\u0631 \u0628\u0627\u0644\u0627 \u0628\u0632\u0646\u06CC\u062F \u062A\u0627 \u0641\u0627\u06CC\u0644 zip (\u0634\u0627\u0645\u0644 config \u0648 resolvers) \u062F\u0631\u06CC\u0627\u0641\u062A \u0634\u0648\u062F\n\u06F2. \u06A9\u0644\u0627\u06CC\u0646\u062A Windows \u0631\u0627 \u062F\u0627\u0646\u0644\u0648\u062F \u0648 \u0646\u0635\u0628 \u06A9\u0646\u06CC\u062F\n\u06F3. \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627 \u0628\u0627\u0632 \u06A9\u0646\u06CC\u062F \u0648 \u0628\u0647 Profiles \u0628\u0631\u0648\u06CC\u062F\n\u06F4. \u0631\u0648\u06CC + \u0628\u0632\u0646\u06CC\u062F \u0633\u067E\u0633 Import TOML\u060C \u0641\u0627\u06CC\u0644 client_config.toml \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\n\u06F5. \u0631\u0648\u06CC Import resolvers \u0628\u0632\u0646\u06CC\u062F\u060C \u0641\u0627\u06CC\u0644 client_resolvers.txt \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\n\u06F6. \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F check \u0622\u0646 \u0627\u0646\u062C\u0627\u0645 \u0634\u0648\u062F \u2014 \u0647\u0645\u0647 resolver\u0647\u0627 \u0631\u0627 \u062A\u0633\u062A \u0645\u06CC\u200C\u06A9\u0646\u062F\u060C \u0686\u0646\u062F \u062F\u0642\u06CC\u0642\u0647 \u0637\u0648\u0644 \u0645\u06CC\u200C\u06A9\u0634\u062F\n\u06F7. \u067E\u0633 \u0627\u0632 \u0627\u062A\u0635\u0627\u0644\u060C \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0631\u0627 \u0631\u0648\u06CC 127.0.0.1:18000 (SOCKS5) \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F",
    masterdns_desktop_title: "macOS / Linux",
